mapper.select:
SELECT id, user_id, reward_key, source_type, xp_delta, point_delta, reward_date, ref_code, reason, created_at
FROM site_reward_ledger WHERE user_id = #{userId}
ORDER BY id DESC LIMIT #{size}

SELECT id, user_id, reward_key, source_type, xp_delta, point_delta, reward_date, ref_code, reason, created_at
FROM site_reward_ledger WHERE user_id = #{userId}
AND xp_delta <> 0
AND point_delta <> 0
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

SELECT reward_date FROM site_reward_ledger
WHERE user_id = #{userId} AND source_type = 'CHECKIN'
ORDER BY reward_date DESC LIMIT #{limit}

SELECT COUNT(*) FROM site_reward_activity
WHERE user_id = #{userId} AND activity_type = #{type}
AND reward_date = #{date}
